),
existing as (
  select extensions.st_unaryunion(
    extensions.st_collect(extensions.st_transform(o.geometry,32616))
  ) as geometry
  from farm_watch.property_operator_paths_v1 o
  join property_row p on p.id=o.property_id
  where o.active
    and o.path_key in ('flat-creek-gravel-access-road','flat-creek-phase3-image-trails')
),
raw_utm as (
  select property_id, geometry, extensions.st_transform(geometry,32616) as geometry_utm
  from raw
),
metrics as (
  select
    r.property_id,
    extensions.st_length(r.geometry_utm) as total_m,
    extensions.st_length(
      extensions.st_intersection(r.geometry_utm,extensions.st_buffer(e.geometry,5))
    ) as within5_m,
    extensions.st_length(
      extensions.st_intersection(r.geometry_utm,extensions.st_buffer(e.geometry,15))
    ) as within15_m
  from raw_utm r cross join existing e
),
points as (
  select
    r.property_id,
    (d).path[1] as idx,
    extensions.st_transform((d).geom,32616) as point_utm
  from raw r
  cross join lateral extensions.st_dumppoints(r.geometry) d
),
segment_points as (
  select
    property_id,
    idx,
    lag(point_utm) over (partition by property_id order by idx) as p0,
    point_utm as p1
  from points
),
segments as (
  select
    s.property_id,
    s.idx,
    extensions.st_makeline(s.p0,s.p1) as geometry_utm
  from segment_points s
  where s.p0 is not null
    and not extensions.st_equals(s.p0,s.p1)
),
classified as (
  select
    s.*,
    case
      when extensions.st_distance(
        extensions.st_lineinterpolatepoint(s.geometry_utm,0.5),
        e.geometry
      ) <= 15.0 then 'overlap'
      else 'novel'
    end as class
  from segments s cross join existing e
),
breaks as (
  select
    c.*,
    case
      when lag(c.class) over (partition by c.property_id order by c.idx) is distinct from c.class then 1
      else 0
    end as is_break
  from classified c
),
run_ids as (
  select
    b.*,
    sum(b.is_break) over (partition by b.property_id order by b.idx) as run_id
  from breaks b
),
runs as (
  select
    property_id,
    class,
    run_id,
    extensions.st_linemerge(extensions.st_collect(geometry_utm)) as geometry_utm
  from run_ids
  group by property_id,class,run_id
),
classified_geometry as (
  select
    property_id,
    class,
    extensions.st_multi(
      extensions.st_collect(extensions.st_transform(geometry_utm,4326))
    ) as geometry
  from runs
  group by property_id,class
),
source_summary as (
