    related_feature_key=excluded.related_feature_key,
    source_context=excluded.source_context,
    notes=excluded.notes,
    geometry=excluded.geometry,
    active=true,
    updated_at=now();

insert into farm_watch.property_operator_observations_v1 (
  property_id,observation_key,observation_kind,observation_state,persistence_status,timing_status,
  observed_at,observed_date_start,observed_date_end,geometry_basis,geometry_precision_m,
  related_product_kind,related_artifact_sha256,related_feature_key,source_context,notes,geometry
)
select
  g.property_id,
  case g.class
    when 'overlap' then 'morning-walk-2025-08-29-existing-overlap'
    else 'morning-walk-2025-08-29-candidate-new'
  end,
  case g.class
    when 'overlap' then 'field_gnss_overlap_existing_access'
    else 'field_gnss_candidate_new_trail'
  end,
  'observed_present',
  'unknown',
  'dated',
  '2025-08-29T14:56:12Z'::timestamptz,
  '2025-08-29'::date,
  '2025-08-29'::date,
  'field_gnss_midpoint_15m_classification_v1',
  15.0,
  'field_gnss_track',
  '134d0f7da1a770fd0d84d82dd0dd0563a2512793223db2511a54c0ffae80984d',
  'flat-creek-access-network',
  s.context || jsonb_build_object(
    'classification_role',g.class,
    'promotion_status',case when g.class='overlap' then 'corroborating_only' else 'candidate_review_only' end
  ),
  case g.class
    when 'overlap' then 'Portions of the raw field traversal whose segment midpoints fall within 15 m of existing canonical gravel-road or imagery-derived trail geometry. Corroborating evidence only; existing geometry is preserved.'
    else 'Portions of the raw field traversal whose segment midpoints fall more than 15 m from existing canonical gravel-road and imagery-derived trail geometry. Candidate under-canopy trail evidence only; not promoted to canonical trail geometry.'
  end,
  g.geometry
from classified_geometry g
join source_summary s using(property_id)
on conflict (property_id,observation_key) do update
set observation_kind=excluded.observation_kind,
    observation_state=excluded.observation_state,
    persistence_status=excluded.persistence_status,
    timing_status=excluded.timing_status,
    observed_at=excluded.observed_at,
    observed_date_start=excluded.observed_date_start,
    observed_date_end=excluded.observed_date_end,
    geometry_basis=excluded.geometry_basis,
    geometry_precision_m=excluded.geometry_precision_m,
    related_product_kind=excluded.related_product_kind,
    related_artifact_sha256=excluded.related_artifact_sha256,
    related_feature_key=excluded.related_feature_key,
    source_context=excluded.source_context,
    notes=excluded.notes,
    geometry=excluded.geometry,
    active=true,
    updated_at=now();

commit;
